let current=0;function show(n){current=Math.max(0,Math.min(n,slides.length-1));slides.forEach((s,i)=>{s.hidden=i!==current;s.setAttribute('aria-hidden',String(i!==current))});const s=slides[current],g=groups.find(x=>x.key===s.dataset.group);picker.value=g.key;id('slideGroup').textContent=g.label;id('slideCount').textContent=`${current+1} / ${slides.length}`;id('slideProgress').max=slides.length;id('slideProgress').value=current+1;id('prevSlide').disabled=current===0;id('nextSlide').disabled=current===slides.length-1;id('deck').setAttribute('aria-label',`${g.label}, slide ${current+1} of ${slides.length}`)}
picker.onchange=()=>{const g=groups.find(x=>x.key===picker.value);if(g)show(g.start)};id('prevSlide').onclick=()=>show(current-1);id('nextSlide').onclick=()=>show(current+1);document.addEventListener('keydown',e=>{
  if(id('courseMenu').open){if(e.key==='Escape'){id('courseMenu').open=false;id('courseToggle').focus()}return}
  if(e.defaultPrevented||e.isComposing||e.altKey||e.ctrlKey||e.metaKey||e.shiftKey)return;
  if(e.key!=='ArrowRight'&&e.key!=='ArrowLeft')return;
  const target=e.target;
  const editingInput=target?.tagName==='INPUT'&&!['radio','checkbox','button','submit','reset'].includes(target.type);
  if(editingInput||target?.isContentEditable||['TEXTAREA','SELECT','AUDIO','VIDEO'].includes(target?.tagName))return;
  // Stop the radio group's native arrow action so turning a page cannot change an answer.
  e.preventDefault();
  show(current+(e.key==='ArrowRight'?1:-1));
  // Move focus out of the hidden question; subsequent arrows and Tab work on the new page.
  slides[current].setAttribute('tabindex','-1');
  slides[current].focus({preventScroll:true});
});
